package playground.pool;
import com.zaxxer.hikari.*; import java.util.concurrent.*;
public class PoolDemo { public static void main(String[] args)throws Exception { var c=new HikariConfig(); c.setJdbcUrl("jdbc:h2:mem:demo"); c.setMaximumPoolSize(2); c.setConnectionTimeout(1000); try(var ds=new HikariDataSource(c)){var workers=Executors.newFixedThreadPool(3);for(int i=1;i<=3;i++){int id=i;workers.submit(()->borrow(ds,id));}workers.shutdown();workers.awaitTermination(5,TimeUnit.SECONDS);}} static void borrow(HikariDataSource ds,int worker){try{System.out.println("worker "+worker+" waits");try(var connection=ds.getConnection()){System.out.println("worker "+worker+" BORROWED "+connection);Thread.sleep(700);System.out.println("worker "+worker+" RETURNS");}}catch(Exception e){System.out.println("worker "+worker+" failed: "+e.getMessage());}}}
